.cinema-bar{position:absolute;left:0;right:0;height:10%;background:#000;z-index:10;transition:height 2.8s cubic-bezier(.2,.8,.2,1)}.cinema-bar.top{top:0}.cinema-bar.bottom{bottom:0}
.cinema-controls{position:absolute;top:max(16px,env(safe-area-inset-top));right:22px;display:flex;gap:8px;z-index:20}.cinema-controls button{background:#080a10c9;border-color:#ffffff25;color:#d5d0c3;font-size:13px;backdrop-filter:blur(10px);padding:9px 13px}.cinema-controls button:focus-visible{outline:2px solid #ffe2a0}
.cinema-brand{position:absolute;top:24px;left:28px;z-index:20;color:#b7a17b;font-size:12px;letter-spacing:.3em;font-weight:700}.cinema-brand b{color:#fff1ce}
.cinema-intro{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;z-index:6;padding:24px;pointer-events:none}.cinema-intro small{font-size:12px;letter-spacing:.5em;color:#c7ac73;opacity:0;transition:opacity .7s}.cinema-intro p{margin:25px 0;font:900 clamp(38px,7vw,112px)/.98 Impact,'Arial Narrow',system-ui,sans-serif;text-transform:uppercase;letter-spacing:.02em;color:#fff5d9;max-width:1100px;opacity:0;transform:scale(1.14);filter:blur(14px);transition:opacity .6s,transform 2.5s cubic-bezier(.16,1,.3,1),filter 1.3s}.cinema-intro p em{font-style:normal;color:#cfab64}.cinema-intro-line{height:1px;width:0;background:linear-gradient(90deg,transparent,#e8c788,transparent);transition:width 2s}
#victory[data-phase="intro"] .cinema-intro p,#victory[data-phase="oath"] .cinema-intro p{opacity:1;transform:scale(1);filter:none}#victory[data-phase="intro"] .cinema-intro small,#victory[data-phase="oath"] .cinema-intro small{opacity:1}#victory[data-phase="intro"] .cinema-intro-line,#victory[data-phase="oath"] .cinema-intro-line{width:min(440px,70vw)}
.cinema-road{position:absolute;inset:15% 5%;z-index:6;display:flex;flex-direction:column;align-items:center;justify-content:center;opacity:0;transform:translateY(30px);transition:opacity .55s,transform 1s;pointer-events:none}.cinema-road>small{font-size:12px;letter-spacing:.4em;text-transform:uppercase;color:#c7ac73}.cinema-road h2{font-family:Impact,'Arial Narrow',system-ui,sans-serif;font-size:clamp(26px,4vw,58px);letter-spacing:.04em;text-transform:uppercase;margin:16px 0 30px}.cinema-route{display:flex;justify-content:center;gap:14px;width:min(1100px,100%)}.cinema-route article{flex:1;min-width:0;max-width:260px;padding:22px 14px;background:linear-gradient(140deg,#332919b3,#080a11de);border:1px solid #d3af653f;position:relative;text-align:left;opacity:0;transform:translateY(28px) rotateY(25deg);transition:opacity .6s,transform .8s;transition-delay:calc(var(--i)*.12s)}.cinema-route article:before{content:'';position:absolute;top:-1px;left:-1px;width:30%;height:2px;background:#efd49b}.cinema-route article small{font-size:10px;color:#b9a783;letter-spacing:.15em;text-transform:uppercase}.cinema-route article strong{display:block;font-size:clamp(15px,1.6vw,23px);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin:12px 0 15px}.cinema-route article span{font-size:clamp(22px,2.5vw,34px);color:#f0d28d;font-variant-numeric:tabular-nums}.cinema-route article i{font-size:12px;font-style:normal;color:#9e978b;display:block;margin-top:4px}
