.cinema-kicker{font-size:12px;letter-spacing:.4em;color:#cbb681;text-transform:uppercase;opacity:0;transition:opacity 1.5s;max-width:90%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cinema-word{font-size:clamp(11px,1vw,14px);letter-spacing:.6em;text-transform:uppercase;color:#ddc28b;margin-top:10px;opacity:0;transition:opacity 1s}
