.cinema-progress{position:absolute;bottom:0;left:0;height:2px;width:0;background:linear-gradient(90deg,#705629,#f5db8b);z-index:21}.cinema-running .cinema-progress{animation:cinema-progress var(--film-duration) linear forwards}.cinema-replay{margin-left:auto;align-self:center;white-space:nowrap}
