@media(max-height:650px) and (min-width:651px){.cinema-trophy-space{height:35%}.cinema-name{font-size:clamp(38px,7vw,80px);margin:7px 0}.cinema-player{font-size:21px}.cinema-recap{margin-top:12px}.cinema-recap strong{font-size:25px}.cinema-signature{margin-top:12px}.cinema-word{margin-top:5px}.cinema-road{inset:17% 7%}}
@media(prefers-reduced-motion:reduce){#victory *{animation:none!important;transition:none!important}#victory canvas,.cinema-flare,.cinema-grain{display:none!important}.cinema-static-cup{display:block}#victory .cinema-name{transform:none!important;filter:none!important}}
