function cinemaMesh(){
 const faces=[];let seed=71;const random=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646};
 function face(points,material='gold'){faces.push({points,material,scatter:[(random()-.5)*7,(random()-.5)*6,(random()-.5)*6],delay:random()*.3})}
 function lathe(profile,n=48,material='gold'){for(let j=0;j<profile.length-1;j++)for(let i=0;i<n;i++){const a=i/n*Math.PI*2,b=(i+1)/n*Math.PI*2,p=profile[j],q=profile[j+1];face([[p[0]*Math.cos(a),p[1],p[0]*Math.sin(a)],[p[0]*Math.cos(b),p[1],p[0]*Math.sin(b)],[q[0]*Math.cos(b),q[1],q[0]*Math.sin(b)],[q[0]*Math.cos(a),q[1],q[0]*Math.sin(a)]],material)}}
 // Sculpted bowl, dark inner well, stem and an octagonal obsidian plinth.
 lathe([[0,-.18],[.18,-.13],[.32,.02],[.51,.22],[.68,.51],[.78,.86],[.85,1.3],[.87,1.4],[.78,1.42],[.76,1.29]]);
 lathe([[.76,1.29],[.66,.9],[.42,.44],[.12,.25],[0,.25]],48,'inside');
 lathe([[.16,-.15],[.14,-.59],[.3,-.81],[.42,-.85],[.42,-.94],[0,-.94]],24);
 lathe([[0,-.96],[.61,-.96],[.7,-1.23],[.7,-1.33],[0,-1.33]],8,'black');
 lathe([[.7,-1.33],[.73,-1.35],[.73,-1.42],[0,-1.42]],8);
 // Curved metallic handles: actual tube faces, not a flat symbol.
 for(const side of[-1,1])for(let j=0;j<18;j++)for(let k=0;k<6;k++){const points=[];for(const[dj,dk]of[[0,0],[1,0],[1,1],[0,1]]){const a=Math.PI/2-(j+dj)/18*Math.PI,b=(k+dk)/6*Math.PI*2;points.push([side*(.55+.22*Math.sin(a)+.58*Math.cos(a)+.075*Math.cos(b)*Math.cos(a)),.74+.58*Math.sin(a)+.075*Math.cos(b)*Math.sin(a),.075*Math.sin(b)])}face(points)}
 // Raised gold diamond on the front of the bowl.
 face([[0,1.12,.84],[.17,.86,.83],[0,.59,.71],[-.17,.86,.83]],'medal');
 return faces;
}
