function startCinema(){
 const final=championship();if(!final)return false;if(cinema)stopCinema();const winner=final.winner,winningScore=number(final.scores[final.players.indexOf(winner)]),path=state.rounds.flatMap((round,r)=>round.filter(m=>m.winner===winner&&!m.bye).map(m=>({m,r}))),dialog=$('victory'),reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 const run={timers:[],raf:0,audio:null,master:null,muted:false,finished:false,begin:performance.now(),focus:document.activeElement,overflow:document.body.style.overflow,resize:()=>{},ownerColor:owner(winner)===0?'#73d9ef':'#f295c6'};cinema=run;
 const title=$('cinemaName');title.replaceChildren();const gold=document.createElement('span');gold.textContent=name(winner);title.append(gold);title.classList.toggle('long-name',name(winner).length>24);$('cinemaPlayer').textContent=state.players[owner(winner)];$('cinemaTournament').textContent=state.title||'Slot Arena';
 $('cinemaRecap').innerHTML=`<div><strong>×${winningScore?.toLocaleString('fr-FR')??'—'}</strong><small>En finale</small></div><div><strong>${path.length}</strong><small>Duels gagnés</small></div><div><strong>${state.slots.length}</strong><small>Slots au départ</small></div>`;
 const highlights=path.length<=4?path:[path[0],...path.slice(-3)];$('cinemaRoute').innerHTML=highlights.map(({m,r},i)=>{const k=m.players.indexOf(winner),opponent=m.players[1-k];return`<article style="--i:${i}"><small>${r===state.rounds.length-1?'Finale':'Tour '+(r+1)}</small><strong>${esc(name(opponent))}</strong><span>×${number(m.scores[k])?.toLocaleString('fr-FR')??'—'}</span><i>Duel remporté</i></article>`}).join('');
 dialog.style.setProperty('--winner-color',run.ownerColor);dialog.dataset.phase='';dialog.dataset.stats='false';dialog.classList.remove('cinema-finished','cinema-no-canvas');dialog.classList.add('cinema-running');$('cinemaMute').disabled=false;$('cinemaMute').setAttribute('aria-pressed','false');$('cinemaChapter').textContent='LE DERNIER ACTE';$('cinemaIntro').innerHTML='Tout se joue.<br><em>Tout se gagne.</em>';document.body.style.overflow='hidden';dialog.showModal();fitCinemaText(dialog);
 function later(fn,t){run.timers.push(setTimeout(()=>{if(cinema===run)fn()},t*1000))}
